select year(ss.sale_date) as sale_year, case when ss.units >= 45 then 'high' when ss.units >= 18 then 'mid' else 'low' end as units_bucket, round(stddev(i.quantity), 2) as stddev_quantity, min(i.last_restock) as first_last_restock from inventory i inner join store_sales ss on i.store_id = ss.store_id and i.product_id = ss.product_id group by year(ss.sale_date), case when ss.units >= 45 then 'high' when ss.units >= 18 then 'mid' else 'low' end
